import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address ownerBefore = c.owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        success; // suppress warning
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Record owner before calling owned()
        address ownerBefore = c.owner();

        // Attempt to call owned() as any caller (including address(0))
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // The rule: owner state variable must not change regardless of call success
        address ownerAfter = c.owner();
        assertTrue(ownerBefore == ownerAfter, "Owner changed after calling owned()");
    }
}

