pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        address originalOwner = c.owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(success);
        assertTrue(c.owner() == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender == c.owner());
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.owned.selector));
        assertTrue(success, "owned() should not revert when called by owner");
    }
}
